/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

/** The ANNUAL term is 12 months — the one term whose discount is admin-configurable. */
export const ANNUAL_TERM_MONTHS = 12;

/**
 * The annual (12-month) commitment discount SHIPPED as the default, and the fallback
 * for the `annual_discount_percent` admin setting (lib/annual-discount.ts).
 *
 * It MUST equal the 12-month `VPS_TERMS` discountPct below: a platform whose
 * `Setting` table has no `annual_discount_percent` row must price the annual term
 * EXACTLY as it did before the setting existed, so no existing annual server's
 * renewal price moves the moment this wiring lands. The setting only ever raises or
 * lowers it deliberately, from the admin Billing panel.
 */
export const DEFAULT_ANNUAL_DISCOUNT_PCT = 20;

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  // Annual is admin-configurable — this is only the SHIPPED default. Every charge
  // path resolves the live rate via `annualDiscountPct()` and passes it through
  // `vpsTermPriceCents`; this constant is what an un-wired caller (and a 2-arg call)
  // falls back to. Keep it === DEFAULT_ANNUAL_DISCOUNT_PCT.
  { months: 12, label: "Annual", short: "1 yr", discountPct: DEFAULT_ANNUAL_DISCOUNT_PCT },
  // Biennial/Triennial are FIXED platform rates (NOT admin-configurable), so for these
  // terms the order and every renewal read the SAME constant here → displayed ===
  // charged === renewed by construction, with no per-account freezing needed. Editing a
  // rate here only reprices NEW orders; any existing longer-term account simply renews
  // at the new (always-cheaper) rate — never an overcharge.
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 30 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 40 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/**
 * The discount percent to apply to a term.
 *
 * For the ANNUAL (12-month) term this is admin-configurable: pass the
 * `annualDiscountPct` resolved from the `annual_discount_percent` setting
 * (lib/annual-discount.ts) and it WINS over the shipped default. Every other term
 * keeps its fixed `VPS_TERMS` rate. Omitting the override — or passing a
 * non-finite value — falls back to the shipped default, so a 2-arg
 * `vpsTermPriceCents` call and any caller that has not been wired up price annual at
 * `DEFAULT_ANNUAL_DISCOUNT_PCT`, i.e. exactly what the platform shipped before.
 * Clamped to 0..90 here as a second line of defence behind the setting reader.
 */
export function termDiscountPct(months: number, annualDiscountPct?: number): number {
  if (months === ANNUAL_TERM_MONTHS && annualDiscountPct != null && Number.isFinite(annualDiscountPct)) {
    return Math.min(90, Math.max(0, annualDiscountPct));
  }
  return vpsTerm(months).discountPct;
}

/**
 * Total charge (cents) for a plan over a term, discount applied.
 *
 * `annualDiscountPct` (optional) overrides the ANNUAL term's discount with the
 * admin-configured rate; see `termDiscountPct`. It is the ONE knob that makes
 * annual billing configurable while keeping this the single price formula —
 * displayed (deploy wizard), charged (lib/order.ts) and renewed (renewalCharge)
 * all call this with the SAME resolved rate, so they cannot disagree.
 */
export function vpsTermPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  const pct = termDiscountPct(months, annualDiscountPct);
  return Math.round(monthlyCents * months * (1 - pct / 100));
}

/**
 * Generic term price — the product-agnostic name for the ONE term formula above.
 * Shared Hosting, Business Email, Game servers and NxCloud all price a term as
 * `monthlyCents × months × (1 − annualDiscount)` exactly the way a VPS does, so
 * they call THIS and there is a single arithmetic for every product+term. It is a
 * thin alias of `vpsTermPriceCents` on purpose: the annual discount is resolved
 * once (order) and re-resolved (renewal) against the SAME setting, so
 * displayed === charged === renewed holds for every product.
 */
export function termPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  return vpsTermPriceCents(monthlyCents, months, annualDiscountPct);
}

/**
 * The terms offered on the NON-VPS products (Shared Hosting, Business Email, Game
 * servers, NxCloud): the full ladder — Monthly, Annual (admin-configurable),
 * Biennial and Triennial — the SAME set VPS sells. Every product prices a term
 * through the one `termPriceCents` formula, so the longer-commitment discounts
 * (20 / 30 / 40%) apply uniformly across the platform.
 */
export const PRODUCT_TERMS: VpsTerm[] = [...VPS_TERMS];

/**
 * Clamp any term input from a product order form to a SUPPORTED product term —
 * one of the `PRODUCT_TERMS` months (1 / 12 / 24 / 36). A malformed / unlisted
 * value can therefore only ever fall back to the cheapest (monthly) term, never
 * grant a longer paid term the customer did not pay for. The order path then prices
 * whatever term this returns through `termPriceCents`, so the charge always matches
 * the term granted.
 */
export function normalizeProductTerm(months: unknown): number {
  const m = Math.round(Number(months));
  return PRODUCT_TERMS.some((t) => t.months === m) ? m : 1;
}

/**
 * Effective monthly-equivalent price after the term discount (for "$/mo" display).
 *
 * `months <= 0` returns the undiscounted monthly price rather than dividing by it.
 * This is not display hygiene — it is a money guard. `prorateDeltaCents`
 * (lib/proration.ts) prices BOTH halves of every upgrade and downgrade credit
 * through this function using `Server.termMonths`, and a 0 there made the division
 * `0 / 0` → NaN, which sails through `Math.round`, through `Math.max(0, delta)`
 * (NaN is not > 0, so the clamp returns NaN, not 0) and into `debitWallet` as the
 * amount to take. The result is a charge that either explodes at the database or,
 * on the credit side, writes NaN where a customer's balance used to be. The column
 * defaults to 1 and every writer clamps to >= 1 today, so this is a latch, not a
 * live bug — but a shared money function must not have a NaN in it.
 */
export function vpsEffectiveMonthly(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  if (!Number.isFinite(months) || months <= 0) return Math.round(monthlyCents);
  return Math.round(vpsTermPriceCents(monthlyCents, months, annualDiscountPct) / months);
}

export type DomainTerm = { years: number; label: string; discountPct: number };

export const DOMAIN_TERMS: DomainTerm[] = [
  { years: 1, label: "1 year", discountPct: 0 },
  { years: 2, label: "2 years", discountPct: 5 },
  { years: 3, label: "3 years", discountPct: 10 },
];

export function domainTerm(years: number): DomainTerm {
  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
}

/** Total charge (cents) for a domain over N years, discount applied. */
export function domainTermPriceCents(perYearCents: number, years: number): number {
  const t = domainTerm(years);
  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
}

/** Add whole months to a date (UTC-safe enough for billing windows). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from);
  d.setMonth(d.getMonth() + months);
  return d;
}
=====ANNUAL-DISCOUNT=====
// Server-only reader for the admin-configurable ANNUAL billing discount. Kept in
// its own tiny module — like lib/dedicated-ip.ts's `dedicatedIpMonthlyCents` and
// lib/backup-upgrade.ts's `backupPlusMonthlyCents` — so a client component (the
// deploy wizard) never drags `lib/settings.ts` (and `db`) into the browser bundle:
// the wizard receives the resolved number as a prop instead.
import { getSettingInt } from "./settings";
import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "./billing-terms";

/**
 * The annual (12-month) commitment discount actually charged, from the admin setting
 * (`annual_discount_percent`, default `DEFAULT_ANNUAL_DISCOUNT_PCT` = 10). The SINGLE
 * source of truth for the annual rate, so the deploy wizard's term card, the order
 * charge (lib/order.ts) and every renewal (renewalCharge) resolve the same number
 * and `displayed === charged === renewed` holds.
 *
 * NORMALISED to a whole percent in 0..90, exactly as `dedicatedIpMonthlyCents`
 * normalises its cents. `getSettingInt` is a raw `Number()` of whatever string sits
 * in the row, so it can return 12.5, -20 or 200; this value flows straight into
 * `vpsTermPriceCents` and from there into a wallet debit, a Stripe amount and an
 * Invoice line. A rate over 100 would price the annual term NEGATIVE (paying the
 * customer to buy), and a negative one would inflate it past 12× monthly — the same
 * class of silent money bug the other add-on readers clamp against. The admin panel
 * refuses out-of-range on write (lib/actions-settings.ts); this clamp defends the
 * charge paths against a hand-written row that slipped past it.
 */
export async function annualDiscountPct(): Promise<number> {
  const v = await getSettingInt("annual_discount_percent", DEFAULT_ANNUAL_DISCOUNT_PCT);
  return Math.min(90, Math.max(0, Math.round(v)));
}

/**
 * The annual discount FROZEN on a Server at sale (`Server.annualDiscountPct`), or null
 * when the row predates that column / never had one. Proration reads THIS (falling back
 * to the live `annualDiscountPct()` for null) so both halves of a resize round trip price
 * against the SAME rate the server was sold at — see the schema note on the column and
 * Finding 2. Pure, no settings read.
 *
 * The cast contains the stale-client gap: the symlinked prod Prisma client's types predate
 * the column, so a loaded `Server` has no `annualDiscountPct` in its type yet (identical at
 * runtime once regenerated at deploy — see lib/promo-redemption.ts). A frozen 0 is honoured
 * (nullish, not falsy), so only a genuinely absent value falls back to live.
 */
export function frozenAnnualDiscountPct(server: unknown): number | null {
  const v = (server as { annualDiscountPct?: number | null } | null | undefined)?.annualDiscountPct;
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

import { db } from "@/lib/db";

/**
 * Server-side helpers for the deploy-wizard funnel (DeployFunnelEvent).
 *
 * Two concerns live here:
 *  1. WRITE — `recordDeployFunnelError` / `recordDeployFunnelComplete` let the
 *     authoritative server paths (the payAndDeploy action, the order/provision
 *     code) stamp an error/complete event even when the browser never sees the
 *     outcome. Both are strictly best-effort: they swallow every failure so they
 *     can never disturb the money path they're instrumenting.
 *  2. READ — `deployFunnels` aggregates the raw events into the admin funnel view:
 *     per product, per step, how many REACHED it, how many of those COMPLETED the
 *     deploy, how many DROPPED OFF, and how many ERRORED (with the top error
 *     messages) — so an admin can tell "stuck on a BUG" from "just abandoned".
 */

const DAY = 86_400_000;
const EVENT_CAP = 100_000;

export type DeployProduct = "vps" | "game" | "hosting" | "email";

/**
 * Typed accessor for the DeployFunnelEvent delegate.
 *
 * The generated Prisma client in this worktree does not yet carry this model
 * (its node_modules is symlinked to prod, which we must not regenerate here — the
 * owner regenerates the client when they apply prisma/manual-migration-deploy-funnel.sql
 * at deploy). This shim types every read/write against the model's real shape so
 * call sites stay type-safe and `tsc` is clean now, and binds to the genuine
 * delegate the moment the client is regenerated. It is the ONLY place that reaches
 * for the delegate, so there is a single seam to delete once the model is generated.
 */
export type DeployFunnelEventRow = {
  id: string;
  userId: string | null;
  visitorId: string | null;
  sessionId: string | null;
  product: string;
  step: string;
  stepIndex: number;
  type: string;
  errorCode: string | null;
  errorMessage: string | null;
  createdAt: Date;
};

type DeployFunnelDelegate = {
  create(args: { data: Partial<DeployFunnelEventRow> }): Promise<DeployFunnelEventRow>;
  findMany(args: {
    where?: Record<string, unknown>;
    select?: Record<string, boolean>;
    take?: number;
    orderBy?: Record<string, "asc" | "desc">;
  }): Promise<DeployFunnelEventRow[]>;
};

function dfe(): DeployFunnelDelegate {
  return (db as unknown as { deployFunnelEvent: DeployFunnelDelegate }).deployFunnelEvent;
}

/** Low-level insert used by the /api/track/deploy-step route (and internally).
 *  Fire-and-forget; never throws. */
export async function insertDeployFunnelEvent(data: Partial<DeployFunnelEventRow>): Promise<void> {
  try {
    await dfe().create({ data });
  } catch {
    /* best-effort analytics — never disturb the caller */
  }
}

/** Record a deploy failure server-side. Fire-and-forget; never throws. */
export async function recordDeployFunnelError(input: {
  product: DeployProduct;
  step: string;
  stepIndex: number;
  errorCode: string;
  errorMessage?: string | null;
  userId?: string | null;
}): Promise<void> {
  await insertDeployFunnelEvent({
    product: input.product,
    step: input.step.slice(0, 60),
    stepIndex: Math.max(0, Math.min(50, Math.round(input.stepIndex))),
    type: "error",
    errorCode: input.errorCode.slice(0, 60),
    errorMessage: input.errorMessage ? input.errorMessage.slice(0, 300) : null,
    userId: input.userId ?? null,
  });
}

/** Record a successful deploy server-side. Fire-and-forget; never throws. */
export async function recordDeployFunnelComplete(input: {
  product: DeployProduct;
  step: string;
  stepIndex: number;
  userId?: string | null;
}): Promise<void> {
  await insertDeployFunnelEvent({
    product: input.product,
    step: input.step.slice(0, 60),
    stepIndex: Math.max(0, Math.min(50, Math.round(input.stepIndex))),
    type: "complete",
    userId: input.userId ?? null,
  });
}

// ---- Read side: aggregate events into the funnel view ----

export type ErrorTally = { code: string | null; message: string | null; count: number };

export type FunnelStep = {
  step: string;
  /** Ordering position (min observed stepIndex for this step within the product). */
  order: number;
  /** Distinct sessions that reached this step. */
  reached: number;
  /** Of those, how many ultimately completed the deploy. */
  completedThrough: number;
  /** Distinct sessions that dropped off AT this step (reached here, not the next). */
  abandoned: number;
  /** Drop-off share at this step (abandoned / reached), 0..1. */
  dropOffRate: number;
  /** Distinct sessions that hit an error on this step. */
  erroredSessions: number;
  /** Total error events on this step (a session can error more than once). */
  errorEvents: number;
  /** Most common error codes/messages on this step. */
  topErrors: ErrorTally[];
};

export type ProductFunnel = {
  product: DeployProduct;
  /** Distinct sessions that reached the first step (top of funnel). */
  started: number;
  /** Distinct sessions with a completed deploy. */
  completed: number;
  /** Distinct sessions that errored anywhere. */
  erroredSessions: number;
  steps: FunnelStep[];
};

/** Stable identity for one wizard run: session, else visitor, else account, else row. */
function identity(e: { sessionId: string | null; visitorId: string | null; userId: string | null; id: string }): string {
  return e.sessionId ?? e.visitorId ?? e.userId ?? e.id;
}

const PRODUCTS: DeployProduct[] = ["vps", "game", "hosting", "email"];

/**
 * Build the per-product deploy funnel over the trailing `days` window. Read-only,
 * window-scoped and take-capped so it stays cheap as the event log grows.
 */
export async function deployFunnels(days = 30): Promise<ProductFunnel[]> {
  const since = new Date(Date.now() - days * DAY);
  const events = await dfe().findMany({
    where: { createdAt: { gte: since } },
    select: {
      id: true,
      product: true,
      step: true,
      stepIndex: true,
      type: true,
      errorCode: true,
      errorMessage: true,
      sessionId: true,
      visitorId: true,
      userId: true,
    },
    take: EVENT_CAP,
    orderBy: { createdAt: "desc" },
  });

  const out: ProductFunnel[] = [];

  for (const product of PRODUCTS) {
    const rows = events.filter((e) => e.product === product);
    if (rows.length === 0) continue;

    // Which runs completed the deploy (for completed-through per step + the
    // top-of-card completed count).
    //
    // IDENTITY RECONCILIATION. Completion is now recorded AUTHORITATIVELY on the
    // server (the shared placeOrder / placeGameOrder / placeHostingOrder success
    // paths — see lib/deploy-funnel `recordDeployFunnelComplete`), where the only
    // stable handle is the signed-in `userId`: a webhook-driven card fulfilment has
    // no browser session. The wizard's own `step` beacons, by contrast, key on the
    // per-tab `sessionId`. So a completion and the steps that led to it resolve to
    // DIFFERENT `identity()` strings, and matching purely on identity would report
    // every completed session as "abandoned at the last step". We therefore match a
    // completion to its run by `userId` (every deploy requires login, so both sides
    // carry one), falling back to identity for any legacy client-side complete that
    // had no account attributed.
    const completedUserIds = new Set<string>();
    const completedIdentityIds = new Set<string>();
    for (const e of rows) {
      if (e.type !== "complete") continue;
      if (e.userId) completedUserIds.add(e.userId);
      else completedIdentityIds.add(identity(e));
    }
    // identity → the account that owns that run, so a `sessionId`-keyed step can be
    // tied back to a `userId`-keyed completion. First non-null userId per identity.
    const userOf = new Map<string, string>();

    // Per-step aggregation.
    type Acc = {
      order: number;
      reached: Set<string>;
      errored: Set<string>;
      errorEvents: number;
      errors: Map<string, { code: string | null; message: string | null; count: number }>;
    };
    const byStep = new Map<string, Acc>();
    const erroredAnywhere = new Set<string>();

    const ensure = (step: string, stepIndex: number): Acc => {
      let a = byStep.get(step);
      if (!a) {
        a = { order: stepIndex, reached: new Set(), errored: new Set(), errorEvents: 0, errors: new Map() };
        byStep.set(step, a);
      } else if (stepIndex < a.order) {
        a.order = stepIndex; // keep the earliest observed position for ordering
      }
      return a;
    };

    for (const e of rows) {
      const id = identity(e);
      if (e.userId && !userOf.has(id)) userOf.set(id, e.userId);
      if (e.type === "step") {
        ensure(e.step, e.stepIndex).reached.add(id);
      } else if (e.type === "error") {
        const a = ensure(e.step, e.stepIndex);
        a.errored.add(id);
        a.errorEvents += 1;
        erroredAnywhere.add(id);
        const key = `${e.errorCode ?? ""}�${e.errorMessage ?? ""}`;
        const cur = a.errors.get(key) ?? { code: e.errorCode, message: e.errorMessage, count: 0 };
        cur.count += 1;
        a.errors.set(key, cur);
      }
    }

    const ordered = [...byStep.entries()]
      .map(([step, a]) => ({ step, a }))
      .sort((x, y) => x.a.order - y.a.order || x.step.localeCompare(y.step));

    // Did the run behind this step identity complete? By userId (the authoritative
    // server-side key) first, then a direct identity hit for legacy client completes.
    const runCompleted = (id: string): boolean => {
      if (completedIdentityIds.has(id)) return true;
      const u = userOf.get(id);
      return u != null && completedUserIds.has(u);
    };

    // Distinct completed runs: accounts that completed, plus any accountless legacy
    // completion. The two sets are disjoint by construction.
    const completed = completedUserIds.size + completedIdentityIds.size;

    const steps: FunnelStep[] = ordered.map(({ step, a }, i) => {
      const reached = a.reached.size;
      const next = ordered[i + 1];
      // Sessions continuing past this step = reached the next step (or, on the last
      // step, completed the deploy). Everyone else abandoned here.
      const continued = next
        ? [...a.reached].filter((id) => next.a.reached.has(id)).length
        : [...a.reached].filter((id) => runCompleted(id)).length;
      const abandoned = Math.max(0, reached - continued);
      const completedThrough = [...a.reached].filter((id) => runCompleted(id)).length;
      const topErrors = [...a.errors.values()].sort((p, q) => q.count - p.count).slice(0, 3);
      return {
        step,
        order: a.order,
        reached,
        completedThrough,
        abandoned,
        dropOffRate: reached > 0 ? abandoned / reached : 0,
        erroredSessions: a.errored.size,
        errorEvents: a.errorEvents,
        topErrors,
      };
    });

    out.push({
      product,
      started: steps[0]?.reached ?? 0,
      completed,
      erroredSessions: erroredAnywhere.size,
      steps,
    });
  }

  return out;
}
=====CLIENT=====
// Client-side deploy-funnel beacons. Dependency-free (no server imports) so it is
// safe to pull into the customer wizard client components. Fires fire-and-forget
// POSTs to /api/track/deploy-step; never throws, never blocks the wizard.

export type DeployProduct = "vps" | "game" | "hosting" | "email";

/** Read the per-tab session id the VisitTracker maintains, so a funnel event can
 *  be tied to the same session as the pageviews. */
function sessionId(): string | null {
  try {
    return window.sessionStorage.getItem("nx_sid");
  } catch {
    return null;
  }
}

function send(payload: Record<string, unknown>): void {
  try {
    const body = JSON.stringify({ ...payload, sessionId: sessionId() });
    if (typeof navigator !== "undefined" && navigator.sendBeacon) {
      navigator.sendBeacon("/api/track/deploy-step", new Blob([body], { type: "application/json" }));
    } else {
      fetch("/api/track/deploy-step", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        keepalive: true,
      }).catch(() => {});
    }
  } catch {
    /* best-effort */
  }
}

/**
 * Record that the user REACHED a wizard step. De-duped per tab-session so a
 * component re-render / strict-mode double-mount doesn't count a step twice — the
 * funnel measures distinct sessions reaching each step.
 */
export function trackDeployStep(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfstep:${product}:${stepIndex}:${step}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* storage disabled — still emit, just without cross-render dedupe */
  }
  send({ product, step, stepIndex, type: "step" });
}

/**
 * Record that a wizard step FAILED (a validation error, or an API/provision call
 * that returned/raised an error). NOT de-duped — every real failure is a signal.
 */
export function trackDeployError(
  product: DeployProduct,
  step: string,
  stepIndex: number,
  errorCode: string,
  errorMessage?: string,
): void {
  if (typeof window === "undefined") return;
  send({ product, step, stepIndex, type: "error", errorCode, errorMessage: errorMessage ?? null });
}

/** Record that the deploy SUCCEEDED (bottom of the funnel). De-duped per session. */
export function trackDeployComplete(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfdone:${product}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* ignore */
  }
  send({ product, step, stepIndex, type: "complete" });
}

