/* ── Isometric server-stack hero illustration. Pure SVG so it themes cleanly and
      needs no asset. Three stacked blades on an iso base with glowing brand edges,
      status LEDs and a soft ground glow — reads clearly as a server. To swap in a
      real render later, replace this element with <img src="…" /> — nothing else
      depends on it. */
function ServerRackArt({ className }: { className?: string }) {
  // Three stacked iso blades; each is a top face + front face + side face.
  const blades = [0, 1, 2];
  return (
    <svg viewBox="0 0 320 300" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} aria-hidden>
      <defs>
        <linearGradient id="hubTop" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#1b2646" />
          <stop offset="1" stopColor="#121a34" />
        </linearGradient>
        <linearGradient id="hubFront" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#131c38" />
          <stop offset="1" stopColor="#0b1226" />
        </linearGradient>
        <linearGradient id="hubSide" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#0d1428" />
          <stop offset="1" stopColor="#080d1c" />
        </linearGradient>
        <linearGradient id="hubEdge" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#8a70fb" />
          <stop offset="1" stopColor="#22d3ee" />
        </linearGradient>
        <radialGradient id="hubGlow" cx="0.5" cy="0.5" r="0.5">
          <stop offset="0" stopColor="#6f47f5" stopOpacity="0.55" />
          <stop offset="1" stopColor="#6f47f5" stopOpacity="0" />
        </radialGradient>
      </defs>

      {/* ground glow */}
      <ellipse cx="160" cy="256" rx="120" ry="30" fill="url(#hubGlow)" />

      {blades.map((b) => {
        // iso projection: each blade sits 46px higher than the last.
        const oy = 190 - b * 46;
        const dx = 120; // half-width along the iso X
        const dz = 60; // depth along iso Y
        const h = 26; // blade thickness (front face)
        const cx = 160;
        // key points of the top rhombus
        const top = `${cx},${oy - dz / 2} ${cx + dx},${oy} ${cx},${oy + dz / 2} ${cx - dx},${oy}`;
        const led = b === 1 ? "#22d3ee" : "#8a70fb";
        return (
          <g key={b}>
            {/* top face */}
            <polygon points={top} fill="url(#hubTop)" stroke="url(#hubEdge)" strokeWidth="1.25" strokeOpacity="0.6" />
            {/* front-left face */}
            <polygon
              points={`${cx - dx},${oy} ${cx},${oy + dz / 2} ${cx},${oy + dz / 2 + h} ${cx - dx},${oy + h}`}
              fill="url(#hubFront)"
            />
            {/* front-right face */}
            <polygon
              points={`${cx},${oy + dz / 2} ${cx + dx},${oy} ${cx + dx},${oy + h} ${cx},${oy + dz / 2 + h}`}
              fill="url(#hubSide)"
            />
            {/* glowing seam along the front bottom edge */}
            <polyline
              points={`${cx - dx},${oy + h} ${cx},${oy + dz / 2 + h} ${cx + dx},${oy + h}`}
              stroke="url(#hubEdge)"
              strokeWidth="1.5"
              strokeOpacity="0.85"
              fill="none"
            />
            {/* drive slots on the left face */}
            {[0, 1, 2].map((s) => (
              <line
                key={s}
                x1={cx - dx + 16 + s * 30}
                y1={oy + 12 + (16 + s * 30) * (dz / 2 / dx)}
                x2={cx - dx + 30 + s * 30}
                y2={oy + 12 + (30 + s * 30) * (dz / 2 / dx)}
                stroke="#2b3a63"
                strokeWidth="3"
                strokeLinecap="round"
              />
            ))}
            {/* status LEDs on the right face */}
            <circle cx={cx + dx - 16} cy={oy + 13} r="3.2" fill={led}>
              <animate attributeName="opacity" values="0.4;1;0.4" dur={`${2 + b * 0.5}s`} repeatCount="indefinite" />
            </circle>
            <circle cx={cx + dx - 16} cy={oy + 21} r="3.2" fill="#22d3ee" opacity="0.5" />
          </g>
        );
      })}
    </svg>
  );
}

export function DeployHub({
  vps,
  hosting,
  game,
  email,
  hostingPromoOn = false,
}: {
  /** null when no active plans/images are configured (VPS deploy unavailable). */
  vps: VpsProps | null;
  hosting: HostingProps;
  /** null when no game families have active tiers. */
  game: GameProps | null;
  email: EmailProps;
  /** The first-month-free promo is RUNNING (offer exists) — drives the marketing
   *  "1st month free" badge on the Shared Hosting tab. The actual $0-vs-full price
   *  at checkout stays gated per-account/IP (hosting.firstMonthFree). */
  hostingPromoOn?: boolean;
}) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const initial = searchParams.get("product");
  const [active, setActive] = useState<DeployProduct>(isProduct(initial) ? initial : "vps");

  const select = useCallback(
    (p: DeployProduct) => {
      setActive(p);
      // Deep-link without a full navigation so the mounted wizard/state is preserved.
      const params = new URLSearchParams(Array.from(searchParams.entries()));
      params.set("product", p);
      router.replace(`/dashboard/deploy?${params.toString()}`, { scroll: false });
    },
    [router, searchParams]
  );

  const activeAccent = ACCENTS[active];

  const wizard = useMemo(() => {
    // Only the ACTIVE product's wizard is ever mounted.
    switch (active) {
      case "vps":
        return vps ? (
          <DeployWizard {...vps} />
        ) : (
          <EmptyState
            title="Deployments are temporarily unavailable"
            sub="No active plans or images are configured. Please check back soon or contact support."
          />
        );
      case "hosting":
        return (
          <div className="space-y-3">
            {/* Display-only promo banner — the charge decision lives in orderHostingAccount.
                Shown only when THIS user is eligible (firstMonthFreeEligible), computed on
                the deploy page exactly as the old hosting page did. */}
            {hosting.firstMonthFree && hosting.plans.length > 0 && (
              <div className="flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
                <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
                Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
              </div>
            )}
            <HostingDeployWizard {...hosting} />
          </div>
        );
      case "game":
        return game ? (
          <GameDeployWizard {...game} />
        ) : (
          <EmptyState
            title="No game plans available yet"
            sub="Game server plans aren't configured yet. Check back soon, or open a ticket and we'll let you know when they're live."
          />
        );
      case "email":
