/**
 * Seed the BUNDLED, free "Domain Inbox" email plan that ships with every
 * domain registered through Nxeon (see lib/domain-inbox-email.ts and
 * purchaseDomain in lib/actions-domains.ts).
 *
 * This mirrors prisma/seed-hosting-email-plans.ts exactly, for the same reason:
 * it must be kept OUT of the paid Business Email storefront, belt-and-braces:
 *   - `active: false`  — every "browse/order a plan" query in the app filters
 *                        `where: { active: true }`, and orderEmailHosting()
 *                        rejects any plan that isn't active, so this can never
 *                        be *bought* (or self-served onto an EXISTING domain)
 *                        through the paid path.
 *   - `priceCents: 0`  — complimentary; no wallet charge is ever taken.
 *   - name "Free Domain Inbox" — the literal string lib/domain-inbox-email.ts's
 *     findDomainInboxPlan() looks up (kept deliberately distinct from the
 *     "…(bundled)" hosting-email names so the two families can never collide).
 *
 * Deliberately small — 1 mailbox, 2 GB — so it reads as a real free tier next to
 * the paid Starter (1 mailbox / 10 GB, see seed-email-plans.ts), not a clone of it.
 *
 * SCOPE: this plan is only ever attached going forward, by purchaseDomain, to a
 * domain at the moment it registers. It is never backfilled onto domains that
 * were already on the platform before this shipped — that is a deliberate,
 * separate decision the product owner has not made.
 *
 * Idempotent: dedupes by `name` and upserts. Safe to re-run.
 *
 * Run: NXEON_DB_TARGET=<db name> npx tsx prisma/seed-domain-inbox-plan.ts
 */
import { PrismaClient } from "@prisma/client";
import { assertDbTarget } from "../scripts/db-target-guard.ts";

// Confirm the target database BEFORE constructing the client — see
// scripts/db-target-guard.ts for why (the 2026-07-26 symlinked-node_modules
// incident). This script is a pure idempotent upsert like its siblings, but a
// fresh script written today has no excuse to skip a one-line safety net.
assertDbTarget("prisma/seed-domain-inbox-plan.ts");

const db = new PrismaClient();

const NAME = "Free Domain Inbox";
const MAILBOXES = 1;
const STORAGE_GB = 2;
const SORT_ORDER = 89; // just ahead of the hosting-bundled plans (90/91/92)

async function main() {
  const data = {
    name: NAME,
    mailboxes: MAILBOXES,
    storageGB: STORAGE_GB,
    priceCents: 0, // complimentary — never charged
    termMonths: 1,
    active: false, // kept OUT of the paid Business Email storefront
    sortOrder: SORT_ORDER,
  };

  // No DB unique constraint on name — dedupe manually (matches seed-email-plans.ts).
  const existing = await db.emailPlan.findFirst({ where: { name: NAME } });
  if (existing) {
    await db.emailPlan.update({ where: { id: existing.id }, data });
    console.log(`  Updated: ${NAME} — ${MAILBOXES} mailbox · ${STORAGE_GB} GB · FREE (bundled, hidden)`);
  } else {
    await db.emailPlan.create({ data });
    console.log(`  Created: ${NAME} — ${MAILBOXES} mailbox · ${STORAGE_GB} GB · FREE (bundled, hidden)`);
  }

  const total = await db.emailPlan.count();
  console.log(`\nFree Domain Inbox plan seeded. Total EmailPlans in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });

