import { db } from "@/lib/db";
import { GAME_FAMILIES } from "@/lib/games";
import { currentPromo } from "@/lib/promotions";
import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
import { annualDiscountPct } from "@/lib/annual-discount";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { planIntroMonthlyCents } from "@/lib/intro-pricing";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import type {
  ExplorerPlan,
  ExplorerGameFamily,
  ProductId,
  PricingExplorerProps,
} from "@/components/marketing/PricingExplorer";

/* Shared assembly of the full PricingExplorer data contract, read LIVE from the
   catalogue. Both the /pricing page and the homepage pricing section render the
   SAME <PricingExplorer /> from this — one source of truth, so the two charts are
   identical. Everything below is DB-fed; nothing here hard-codes a price, and the
   caller supplies only the `reviewBadges` ReactNode (not serialisable). */

/* Deploy CTA target — the same href the previous pricing page's plan CTAs used. */
const DEPLOY_HREF = "/register";
const DOMAINS_HREF = "/domains";

function gb(mb: number): string {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}
/** Base MONTHLY price for a plan. VPS/Hosting store a monthly `priceCents`; Email &
 *  Game store it per `termMonths`, so normalise to a per-month figure. All display
 *  math downstream runs THIS through termPriceCents — the formula checkout charges. */
function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
  const t = p.termMonths ?? 1;
  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
}

const INCLUDED: Record<ProductId, string[]> = {
  vps: ["Full root access", "Dedicated IPv4", "NVMe SSD", "DDoS protection", "Auto backups", "1-click reinstall"],
  game: ["DDoS protection", "Full control panel", "Instant deploy", "Game file manager", "Custom jar support"],
  hosting: ["Free SSL", "1-click WordPress", "Free migration", "cPanel included", "DDoS protection"],
  email: ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"],
  domains: ["Free WhoisGuard privacy", "Full DNS management", "One-click VPS pointing", "Auto-renew"],
};

const GAME_NAME: Record<string, string> = {
  minecraft: "Minecraft", valheim: "Valheim", rust: "Rust", palworld: "Palworld", cs2: "CS2", terraria: "Terraria",
};

/** The full PricingExplorer data contract MINUS `reviewBadges` (a ReactNode the
 *  caller supplies). Fully serialisable so it can cross the server→client boundary. */
export type PricingExplorerData = Omit<PricingExplorerProps, "reviewBadges">;

export async function getPricingExplorerData(): Promise<PricingExplorerData> {
  // Every product line's prices, read LIVE from the catalogue. Nothing below is
  // hard-coded; a catalogue edit or deactivation propagates here automatically.
  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
  ]);

  // The REAL, live annual discount + add-on prices (admin settings) — never
  // marketing constants. These are the SAME figures lib/order.ts bills, so the
  // add-on builder's "your build" total is displayed === charged.
  const [annualPct, backupPlusCents, extraDiskGbCents] = await Promise.all([
    annualDiscountPct(),
    backupPlusMonthlyCents(),
    extraDiskPerGbCents(),
  ]);

  // Promo copy from the single source of truth — surfaced ONLY where the owner
  // scoped it (shared web hosting) via firstMonthFreeAppliesTo("HOSTING"). It is
  // passed as a nullable label so the badge cannot render on any other product.
  const hostingPromoLabel = firstMonthFreeAppliesTo("HOSTING") ? currentPromo(new Date()).label : null;

  // ── VPS: 4 tiers. Middle = "Most popular" (violet), last = "Best value" (cyan). ──
  const vps: ExplorerPlan[] = vpsPlans.map((p, i) => ({
    id: p.id,
    name: p.name,
    monthlyCents: monthlyOf(p),
    // Optional LOW intro price → the card shows "$intro first term, then $regular/mo".
    // Null (no intro set) leaves the card at the plain regular price, unchanged.
    introMonthlyCents: planIntroMonthlyCents(p),
    badge:
      vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2)
        ? "popular"
        : vpsPlans.length >= 3 && i === vpsPlans.length - 1
          ? "best"
          : undefined,
    specs: [
      { label: "CPU", value: `${p.cpuCores} vCPU` },
      { label: "RAM", value: gb(p.ramMB) },
      { label: "Storage", value: `${p.diskGB} GB NVMe` },
      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
    ],
    href: DEPLOY_HREF,
  }));

  // ── Hosting: featured tier gets the violet "Most popular" badge. ──
  const hosting: ExplorerPlan[] = hostingPlans.map((p, i) => ({
    id: p.id,
    name: p.name,
    monthlyCents: monthlyOf(p),
    badge: p.featured || (hostingPlans.length >= 3 && i === Math.floor((hostingPlans.length - 1) / 2)) ? "popular" : undefined,
    specs: [
      { label: "Disk", value: `${p.diskGB} GB` },
      { label: "Websites", value: String(p.maxSites) },
      { label: "Databases", value: String(p.maxDatabases) },
      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
      { label: "Mailboxes", value: p.mailboxes < 0 ? "Unlimited" : String(p.mailboxes) },
    ],
    href: DEPLOY_HREF,
  }));

  // ── Business Email: mailbox plans. ──
  const email: ExplorerPlan[] = emailPlans.map((p, i) => ({
    id: p.id,
    name: p.name,
    monthlyCents: monthlyOf(p),
    badge: emailPlans.length >= 3 && i === Math.floor((emailPlans.length - 1) / 2) ? "popular" : undefined,
    specs: [
      { label: "Mailboxes", value: `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}` },
      { label: "Storage", value: `${p.storageGB} GB / mailbox` },
      { label: "Filtering", value: "Spam & virus" },
      { label: "Sync", value: "Calendars & contacts" },
    ],
    href: DEPLOY_HREF,
  }));

  // ── Game servers: grouped by family, canonical order, families with real plans only. ──
  const byGame = new Map<string, typeof gamePlans>();
  for (const g of gamePlans) {
    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
    byGame.get(g.gameFamily)!.push(g);
  }
  const games: ExplorerGameFamily[] = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0).map((fam) => {
    const tiers = (byGame.get(fam) ?? []).slice().sort((a, b) => a.priceCents - b.priceCents);
    return {
      id: fam,
      name: GAME_NAME[fam] ?? fam,
      plans: tiers.map((t) => ({
        id: t.id,
        name: t.name,
        monthlyCents: monthlyOf(t),
        badge: t.featured ? ("popular" as const) : undefined,
        specs: [
          { label: "RAM", value: gb(t.ramMB) },
          { label: "CPU", value: `${t.cpuCores} vCPU` },
          { label: "Storage", value: `${t.diskGB} GB` },
          ...(t.slots != null ? [{ label: "Slots", value: `${t.slots} slots` }] : []),
        ],
        href: DEPLOY_HREF,
      })),
    };
  });

  const tlds = POPULAR_TLDS.map((t) => ({ tld: t.tld, fromCents: t.fromCents }));

  return {
    annualPct,
    vps,
    hosting,
    email,
    games,
    tlds,
    hostingPromoLabel,
    included: INCLUDED,
    domainsHref: DOMAINS_HREF,
    backupPlusCents,
    extraDiskPerGbCents: extraDiskGbCents,
  };
}

/**
 * The small persistent "what you're buying, right now" bar that follows the
 * customer through every wizard step — the same pattern the marketing
 * pricing cards use (plan name + price + a Continue button attached to it),
 * brought into the wizard so the price never disappears off-screen while
 * configuring a long step.
 *
 * Deliberately does NOT reimplement the Continue/Deploy logic — it calls the
 * exact same `onContinue` the wizard's own button uses, so there is still
 * only ONE place that decides what happens next. On the final step, once the
 * embedded Payment form is showing, there is no single "continue" action
 * left to trigger (paying requires the actual card/PayPal/Coinbase form
 * above) — `onContinue` is omitted in that case and the bar shows price only.
 */
export function WizardStickyCart({
  planName,
  priceLabel,
  disabled,
  onContinue,
  continueLabel = "Continue",
}: {
  planName: string;
  priceLabel: string;
  disabled?: boolean;
  /** Omit entirely (rather than pass a no-op) once there's no single action
   *  left for this bar to trigger — e.g. the embedded Payment form is showing. */
  onContinue?: () => void;
  continueLabel?: string;
}) {
  return (
    <div className="sticky bottom-4 z-10 mt-6 flex items-center justify-between gap-4 rounded-2xl border border-white/10 bg-navy-950/95 px-5 py-3.5 shadow-[0_12px_40px_-8px_rgba(0,0,0,0.6)] backdrop-blur-md">
      <div className="min-w-0">
