  // helper) so the admin funnel shows how far people get. Mirrors DeployWizard.
  useEffect(() => {
    trackDeployStep("email", ORDER_STEPS[step] ?? String(step), step);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  // Deploy-funnel: when the order action returns an error, record it against the
  // current step so a BUG is distinguishable from abandonment.
  useEffect(() => {
    if (error) trackDeployError("email", ORDER_STEPS[step] ?? "Review", step, "ORDER_ERROR", error);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [error]);

  const selected = plans.find((p) => p.id === planId);
  // Email plans are seeded monthly, so priceCents is the per-month base. Price the
  // chosen term through the SAME formula the server charges (termPriceCents).
  const termCharge = selected ? termPriceCents(selected.priceCents, termMonths, annualDiscountPct) : 0;
