  const split = walletSplit({ dueCents: termCharge, balanceCents, useWallet });
  const cardCents = split.cardCents;
  const walletApplied = split.walletApplied;
  const registered = new Set(suggestedDomains.map((d) => d.toLowerCase()));
  const trimmed = domain.trim().toLowerCase();
  const isExternal = trimmed.length > 0 && !registered.has(trimmed);

  function submit() {
    if (!domain.trim()) {
      setError("Enter a domain.");
      return;
    }
    setError(null);
    setOk(false);
