/**
 * Shared per-server DEDICATED IP purchase core — the money path for adding a
 * dedicated public IPv4 to a server that does NOT already have one.
 *
 * Mirrors lib/disk-expand.ts (which itself mirrors lib/resize.ts) line-for-line
 * in shape: a pure `*Quote` function re-validated by `apply*`, used by both the
 * wallet flow (lib/actions-dedicated-ip.ts) and the Stripe confirm route so a
 * paid checkout can apply the purchase immediately. Plain server module (NOT
 * "use server").
 *
 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
 * Identical argument to lib/disk-expand.ts: one quote function, one wallet debit
 * inside the same transaction that creates the job, and the card path credits
 * only the card remainder before debiting the full proration on confirm.
 *
 * ─── ROLLBACK SAFETY (real infra, real money) ───────────────────────────────
 * The actual IP claim + OVH Virtual MAC creation + Proxmox network reconfig all
 * happen in the WORKER (`ASSIGN_DEDICATED_IP`, worker/index.ts), never here —
 * exactly like DISK_EXPAND never touches Proxmox synchronously inside the
 * action. That keeps "charge" and "allocate" as two separate steps that can
 * each fail independently without corrupting the other:
 *   - If nothing is charged, no job is ever created (both happen in one
 *     `$transaction`), so nothing is ever allocated.
 *   - If the job's `allocateDedicatedIp` call can't claim a pool IP (or OVH
 *     errors), it throws BEFORE touching the DB (see lib/dedicated-ip.ts's own
 *     rollback-on-failure) and the job fails/retries; a terminal failure is
 *     refunded by `reconcileFailedJob` in worker/index.ts, mirroring RESIZE.
 */
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { remainingMonths } from "./proration";
import { extraDiskProrateCents } from "./extra-disk";
import { dedicatedIpMonthlyCents, freeCount } from "./dedicated-ip";

export class DedicatedIpPurchaseError extends Error {}

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
}

